<?php
/** Slice 3 — production (a prep made into stock) and waste at three stages (ledger.md "Proof": Production, Waste). Order-independent: deltas. */
require __DIR__ . '/lib.php';
$w = ledger_world();
$bea = person(28); $dana = person(30); $ann = person(29);
stock_in($dana, $w['walkin'], [['ingredient' => 'L-CHK', 'qty' => 1, 'unit' => 'case', 'weight_qty' => 40, 'weight_unit' => 'lb', 'unit_cost' => 3.10], ['ingredient' => 'L-CHK', 'qty' => 1, 'unit' => 'case', 'weight_qty' => 40, 'weight_unit' => 'lb', 'unit_cost' => 3.10], ['ingredient' => 'L-EGG', 'qty' => 1, 'unit' => 'case', 'unit_cost' => 54]], $w['sysco']);
$avgChk = avg_cost($w['chicken']);
$chk = on_hand($w['chicken'], DOWNTOWN, $w['walkin']); $stk = on_hand($w['stock'], DOWNTOWN, $w['walkin']);

echo "1. The batch form and its preview\n";
$h = page($bea, '/production/new?recipe=' . $w['r_stock'])['body'];
ok(str_contains($h, 'id="production-form"') && str_contains($h, 'id="production-form-field-batches"') && str_contains($h, 'id="production-preview"'), 'the batch form with the preview under it');
ok(str_contains($h, 'id="production-preview-table"') && str_contains($h, 'SMOKE Chicken breast'), 'the preview lists the chicken the stock prep consumes');
$p = page($bea, '/production/preview?recipe=' . $w['r_stock'] . '&batches=1', ['headers' => ['HX-Request: true']])['body'];
ok(str_contains($p, '2,000 g') || str_contains($p, '2 kg'), 'Pattern A: 1 batch needs 2 kg of chicken');
ok(str_contains($p, 'id="production-preview-output"') && (str_contains($p, '3,600 ml') || str_contains($p, '3.6 l')), 'and makes 3 600 ml of stock (4 l less 10 % loss)');
$p = page($bea, '/production/preview?recipe=' . $w['r_stock'] . '&batches=100', ['headers' => ['HX-Request: true']])['body'];
ok(preg_match('/id="production-preview-row-[0-9]+" class="text-danger"/', $p) === 1 && str_contains($p, '— short'), '100 batches: the short line is red (a warning — the post is not stopped)');
$p = page($bea, '/production/preview?recipe=' . $w['r_sand'] . '&batches=1', ['headers' => ['HX-Request: true']])['body'];
ok(str_contains($p, 'prep recipe'), 'a menu item in the preview: it says only a prep is produced');

echo "2. Post a batch\n";
$r = post($bea, '/production/save.php', ['recipe' => $w['r_stock'], 'batches' => '1', 'area' => $w['walkin']]);
$b1 = last_id('production_batches');
ok($r['code'] === 302 && str_contains($r['location'], '/production/' . $b1) && one('SELECT status FROM production_batches WHERE id = :b', ['b' => $b1]) === 'posted', 'Bea posts 1 batch of the stock prep');
$tx = array_column(q("SELECT txn_type, ingredient_id, qty_base, unit_cost_per_base FROM inventory_transactions WHERE reference_kind = 'production' AND reference_id = :b", ['b' => $b1]), null, 'txn_type');
ok(near($tx['production_out']['qty_base'] ?? null, -2000) && (int) ($tx['production_out']['ingredient_id'] ?? 0) === $w['chicken'] && near($tx['production_out']['unit_cost_per_base'] ?? null, $avgChk, 0.000001), 'production_out: 2 000 g of chicken at the running cost');
$sum = 2000 * $avgChk;
ok(near($tx['production_in']['qty_base'] ?? null, 3600) && near($tx['production_in']['unit_cost_per_base'] ?? null, $sum / 3600, 0.000001), 'production_in: 3 600 ml of stock at Σ ÷ 3 600');
ok(near(one('SELECT cost_total FROM production_batches WHERE id = :b', ['b' => $b1]), $sum, 0.01), "cost_total on the batch ($" . number_format($sum, 2) . ')');
ok((int) one("SELECT count(*) FROM price_history WHERE reference_kind = 'production' AND reference_id = :b AND source_kind = 'production' AND ingredient_id = :s", ['b' => $b1, 's' => $w['stock']]) === 1, 'price_history source production for the stock');
ok(near(on_hand($w['chicken'], DOWNTOWN, $w['walkin']), $chk - 2000) && near(on_hand($w['stock'], DOWNTOWN, $w['walkin']), $stk + 3600), 'chicken 2 kg less, stock 3.6 l more at the Walk-in');
ok((int) one('SELECT recipe_version_id FROM production_batches WHERE id = :b', ['b' => $b1]) === (int) one('SELECT ri_recipe_version_on(:r, current_date)', ['r' => $w['r_stock']]), 'the batch records the version in force');
$ev = q("SELECT recipe_id, after FROM activity_log WHERE action = 'production.post' AND entity_id = :b", ['b' => $b1])[0] ?? null;
ok($ev !== null && (int) $ev['recipe_id'] === $w['r_stock'] && !str_contains((string) $ev['after'], 'cost_total'), 'production.post logged with recipe_id, and no cost for Bea (Kitchen sees none)');
$h = page($dana, '/production/' . $b1)['body'];
ok(str_contains($h, 'id="production-consumed-table"') && str_contains($h, 'id="production-made-table"') && str_contains($h, 'id="production-cost-total"') && str_contains($h, '$' . number_format($sum, 2)), "the batch's view to Dana: what it consumed and made, with the cost");
$hb = page($bea, '/production/' . $b1)['body'];
ok(str_contains($hb, 'id="production-consumed-table"') && !str_contains($hb, '$' . number_format($sum, 2)), '…and to Bea without the cost');
$r = post($dana, '/production/save.php', ['recipe' => $w['r_sand'], 'batches' => '1', 'area' => $w['walkin']]);
ok($r['code'] === 422 && has($r, 'Only a prep recipe is produced'), 'a menu-item recipe: 422 "Only a prep recipe is produced"');
$r = post($dana, '/production/save.php', ['recipe' => $w['r_stock'], 'batches' => '0', 'area' => $w['walkin']]);
ok($r['code'] === 422 && has($r, 'more than zero'), 'zero batches: 422');
$r = post($ann, '/production/save.php', ['recipe' => $w['r_stock'], 'batches' => '1', 'area' => $w['walkin']]);
ok($r['code'] === 403, 'a Viewer cannot produce (403)');

echo "3. An actual output; a draft; cancel\n";
$avgChk = avg_cost($w['chicken']);
$r = post($dana, '/production/save.php', ['recipe' => 'L-R-STOCK', 'batches' => '1', 'area' => $w['walkin'], 'output_qty' => '3.4', 'output_unit' => 'l']);
$b2 = last_id('production_batches');
$in2 = (float) one("SELECT unit_cost_per_base FROM inventory_transactions WHERE reference_kind = 'production' AND reference_id = :b AND txn_type = 'production_in'", ['b' => $b2]);
ok($r['code'] === 302 && near(one('SELECT output_qty_base FROM production_batches WHERE id = :b', ['b' => $b2]), 3400) && near($in2, 2000 * $avgChk / 3400, 0.000001), 'an actual output of 3.4 l: 3 400 ml at Σ ÷ 3 400');
ok($in2 > (float) ($tx['production_in']['unit_cost_per_base'] ?? 0), '…so the cost per ml is higher than at the full yield');
$r = post($dana, '/production/save.php', ['recipe' => $w['r_stock'], 'batches' => '0.5', 'area' => $w['walkin'], 'draft' => 'yes', 'notes' => 'for tonight']);
$b3 = last_id('production_batches');
ok($r['code'] === 302 && one('SELECT status FROM production_batches WHERE id = :b', ['b' => $b3]) === 'draft' && (int) one("SELECT count(*) FROM inventory_transactions WHERE reference_kind = 'production' AND reference_id = :b", ['b' => $b3]) === 0, 'a draft of half a batch: saved, nothing moved');
$h = page($dana, '/production/' . $b3)['body'];
ok(str_contains($h, 'id="production-post-btn"') && str_contains($h, 'id="production-cancel-btn"'), 'the draft offers Post and Cancel');
$r = post($dana, '/production/save.php', ['batch' => $b3]);
ok($r['code'] === 302 && one('SELECT status FROM production_batches WHERE id = :b', ['b' => $b3]) === 'posted' && near(one("SELECT qty_base FROM inventory_transactions WHERE reference_kind = 'production' AND reference_id = :b AND txn_type = 'production_out'", ['b' => $b3]), -1000), 'then posted: 1 000 g of chicken out');
$r = post($dana, '/production/save.php', ['batch' => $b3]);
ok($r['code'] === 422, 'posting it again: 422');
post($dana, '/production/save.php', ['recipe' => $w['r_stock'], 'area' => $w['walkin'], 'draft' => 'yes']);
$b4 = last_id('production_batches');
$r = post($dana, '/production/cancel.php', ['batch' => $b4]);
ok($r['code'] === 302 && one('SELECT status FROM production_batches WHERE id = :b', ['b' => $b4]) === 'cancelled', 'a draft cancelled');
$r = post($dana, '/production/cancel.php', ['batch' => $b1]);
ok($r['code'] === 422, 'a posted batch is not cancelled (422)');
$h = page($dana, '/production/')['body'];
ok(str_contains($h, 'id="batch-row-' . $b1 . '"') && str_contains($h, 'id="batch-row-' . $b4 . '"'), 'the production list');

echo "4. Waste\n";
$h = page($bea, '/waste/new')['body'];
ok(str_contains($h, 'id="waste-form"') && str_contains($h, 'id="waste-form-field-stage-ingredient"') && str_contains($h, 'id="waste-form-field-stage-prep"') && str_contains($h, 'id="waste-form-field-stage-plate"'), 'the waste form: three stage buttons');
ok(str_contains($h, 'id="waste-form-field-gross_weight_g"') && str_contains($h, 'id="waste-form-field-tare_g"') && str_contains($h, 'id="waste-form-field-photo"'), '…the scale fields and a photo');
$chk = on_hand($w['chicken'], DOWNTOWN, $w['walkin']); $stk = on_hand($w['stock'], DOWNTOWN, $w['walkin']); $egg = on_hand($w['egg'], DOWNTOWN, $w['walkin']);
$r = post($bea, '/waste/save.php', ['stage' => 'plate', 'recipe' => 'L-R-SAND', 'qty' => '1', 'unit' => 'portion', 'reason' => 'returned_dish', 'station' => 'pass']);
$w1 = last_id('waste_logs');
ok($r['code'] === 302 && str_contains($r['location'], 'highlight=' . $w1) && str_contains($r['location'], '#waste-row-' . $w1), 'Bea logs a returned sandwich; lands on the list with the row highlighted');
$wt = array_column(q("SELECT ingredient_id, qty_base FROM inventory_transactions WHERE reference_kind = 'waste' AND reference_id = :w AND txn_type = 'waste'", ['w' => $w1]), 'qty_base', 'ingredient_id');
ok(count($wt) === 3, 'three waste rows');
ok(near($wt[$w['chicken']] ?? null, -188.89, 0.01) && near($wt[$w['stock']] ?? null, -50) && near($wt[$w['egg']] ?? null, -1), 'chicken 188.9 g (170 g at 90 %), stock 50 ml (the prep from stock), an egg');
$cost1 = (float) one("SELECT sum(-qty_base * unit_cost_per_base) FROM inventory_transactions WHERE reference_kind = 'waste' AND reference_id = :w", ['w' => $w1]);
ok(near(one('SELECT cost FROM waste_logs WHERE id = :w', ['w' => $w1]), $cost1, 0.01) && $cost1 > 0, 'the cost on the log = Σ of its rows at the running cost');
ok(near(on_hand($w['chicken'], DOWNTOWN, $w['walkin']), $chk - 188.89, 0.01) && near(on_hand($w['stock'], DOWNTOWN, $w['walkin']), $stk - 50), 'out of the depletion area (the Walk-in)');
$h = page($bea, $r['location'])['body'];
ok(str_contains($h, 'id="waste-row-' . $w1 . '" class="table-warning"'), 'the row highlighted on the list');
$ev = q("SELECT recipe_id, after FROM activity_log WHERE action = 'waste.log' AND entity_id = :w", ['w' => $w1])[0] ?? null;
ok($ev !== null && (int) $ev['recipe_id'] === $w['r_sand'] && !str_contains((string) $ev['after'], '"cost"'), 'waste.log logged with recipe_id and no cost (Bea)');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-EGG', 'qty' => '1', 'unit' => 'flat', 'reason' => 'breakage', 'area' => $w['walkin']]);
$w2 = last_id('waste_logs');
ok($r['code'] === 302 && near(one('SELECT qty_base FROM waste_logs WHERE id = :w', ['w' => $w2]), 30) && near(on_hand($w['egg'], DOWNTOWN, $w['walkin']), $egg - 31), 'a dropped flat by count: 30 eggs');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-CHK', 'gross_weight_g' => '1240', 'tare_g' => '240', 'reason' => 'trim', 'area' => $w['walkin']]);
$w3 = last_id('waste_logs');
ok($r['code'] === 302 && near(one('SELECT qty_base FROM waste_logs WHERE id = :w', ['w' => $w3]), 1000) && near(one('SELECT gross_weight_g FROM waste_logs WHERE id = :w', ['w' => $w3]), 1240) && near(one('SELECT tare_g FROM waste_logs WHERE id = :w', ['w' => $w3]), 240), 'weighed chicken: gross 1 240 g, tare 240 g → 1 000 g');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-CHK', 'gross_weight_g' => '200', 'tare_g' => '240', 'reason' => 'trim']);
ok($r['code'] === 422 && has($r, 'tare is less than'), 'a tare above the gross: 422');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-LIME', 'gross_weight_g' => '500', 'tare_g' => '0', 'reason' => 'spoilage']);
ok($r['code'] === 422 && has($r, 'each-weight'), 'limes on the scale (no each-weight): 422 in the schema\'s words');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-EGG', 'qty' => '1', 'unit' => 'each', 'reason' => 'theft']);
ok($r['code'] === 422 && has($r, 'not a waste reason'), 'a reason theft: 422 "not a waste reason"');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'recipe' => 'L-R-STOCK', 'qty' => '1', 'reason' => 'spoilage']);
ok($r['code'] === 422, 'an ingredient-stage waste naming a recipe: 422');
$r = post($bea, '/waste/save.php', ['stage' => 'plate', 'recipe' => 'L-R-SAND', 'qty' => '1', 'unit' => 'kg', 'reason' => 'plate_waste']);
ok($r['code'] === 422 && has($r, 'portions or batches'), 'a recipe in kg: 422');
$r = post($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-EGG', 'qty' => '1', 'unit' => 'each', 'reason' => 'breakage', 'business_date' => date('Y-m-d', strtotime('+1 day'))]);
ok($r['code'] === 422 && has($r, 'not in the future'), 'a day in the future: 422');
$chk = on_hand($w['chicken'], DOWNTOWN, $w['walkin']);
$r = post($bea, '/waste/save.php', ['stage' => 'prep', 'recipe' => 'L-R-STOCK', 'qty' => '0.5', 'unit' => 'batch', 'reason' => 'burned']);
$w4 = last_id('waste_logs');
$wt = array_column(q("SELECT ingredient_id, qty_base FROM inventory_transactions WHERE reference_kind = 'waste' AND reference_id = :w", ['w' => $w4]), 'qty_base', 'ingredient_id');
ok($r['code'] === 302 && count($wt) === 1 && near($wt[$w['chicken']] ?? null, -1000), 'prep-stage waste of half a batch of stock: 1 000 g of chicken (the prep exploded to raw — the batch was never posted)');
ok(near(on_hand($w['chicken'], DOWNTOWN, $w['walkin']), $chk - 1000), 'chicken 1 kg less');
$png = sys_get_temp_dir() . '/ri-waste-photo.png';
file_put_contents($png, base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=='));
$r = post_file($bea, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-LIME', 'qty' => '3', 'unit' => 'each', 'reason' => 'spoilage', 'area' => $w['walkin']], 'photo', $png, 'image/png');
$w5 = last_id('waste_logs');
$att = (int) one('SELECT photo_attachment_id FROM waste_logs WHERE id = :w', ['w' => $w5]);
ok($r['code'] === 302 && $att > 0 && (int) one("SELECT count(*) FROM attachments WHERE id = :a AND record_type = 'waste_log' AND record_id = :w", ['a' => $att, 'w' => $w5]) === 1, 'a photo saved as an attachment of the log');
$after = (string) one("SELECT after FROM activity_log WHERE action = 'waste.log' AND entity_id = :w", ['w' => $w5]);
ok(str_contains($after, '"photo": true') && !str_contains($after, 'iVBOR') && !str_contains($after, 'ri-waste-photo'), '…never in the log payload (only that there is one)');
ok(str_contains(page($dana, '/waste/' . $w5)['body'], 'id="waste-photo"'), 'the log shows its photo');

echo "5. Review, void, the week\n";
$r = post($bea, '/waste/review.php', ['waste' => $w1]);
ok($r['code'] === 403, 'Bea (no waste.review) cannot review: 403');
$r = post($dana, '/waste/review.php', ['waste' => $w1]);
ok($r['code'] === 302 && one('SELECT status FROM waste_logs WHERE id = :w', ['w' => $w1]) === 'reviewed' && (int) one("SELECT count(*) FROM activity_log WHERE action = 'waste.review' AND entity_id = :w", ['w' => $w1]) === 1, 'Dana reviews the sandwich: reviewed, logged');
$egg = on_hand($w['egg'], DOWNTOWN, $w['walkin']);
$r = post($dana, '/waste/void.php', ['waste' => $w2, 'note' => 'found unbroken']);
ok($r['code'] === 302 && one('SELECT status FROM waste_logs WHERE id = :w', ['w' => $w2]) === 'voided', 'Dana voids the flat');
ok((int) one("SELECT count(*) FROM inventory_transactions WHERE txn_type = 'reversal' AND reverses_id IN (SELECT id FROM inventory_transactions WHERE reference_kind = 'waste' AND reference_id = :w)", ['w' => $w2]) === 1 && near(on_hand($w['egg'], DOWNTOWN, $w['walkin']), $egg + 30), 'one reversal; the 30 eggs are back');
$r = post($dana, '/waste/void.php', ['waste' => $w2]);
ok($r['code'] === 422, 'voiding it again: 422');
$to = (string) one('SELECT (now() AT TIME ZONE ri_site_timezone(101))::date'); $from = date('Y-m-d', strtotime($to . ' -6 days'));
$sum = q('SELECT stage, sum(entries) AS n, sum(cost) AS c FROM ri_share_waste_summary(101, :f::date, :t::date) GROUP BY stage', ['f' => $from, 't' => $to]);
$sum = array_column($sum, null, 'stage');
$h = page($dana, '/waste/')['body'];
$okTiles = true;
foreach (['ingredient', 'prep', 'plate'] as $s) {
    preg_match('/id="waste-tile-' . $s . '-entries">(\d+)</', $h, $m1); preg_match('/id="waste-tile-' . $s . '-cost">([^<]+)</', $h, $m2);
    $okTiles = $okTiles && (int) ($m1[1] ?? -1) === (int) ($sum[$s]['n'] ?? 0) && trim($m2[1] ?? '') === '$' . number_format((float) ($sum[$s]['c'] ?? 0), 2);
}
ok($okTiles, "the week's tiles by stage agree with ri_share_waste_summary() (entries and cost; the voided flat out)");
$rows = q('SELECT reason, sum(entries) AS n FROM ri_share_waste_summary(101, :f::date, :t::date) GROUP BY reason', ['f' => $from, 't' => $to]);
$okReasons = $rows !== [];
foreach ($rows as $x) { $okReasons = $okReasons && preg_match('/id="waste-reason-row-' . preg_replace('/[^a-z0-9]+/', '-', strtolower($x['reason'])) . '"><td>[^<]+<\/td><td class="text-end">' . (int) $x['n'] . '</', $h) === 1; }
ok($okReasons, '…and so does the reason table');
$h = page($ann, '/waste/')['body'];
ok(str_contains($h, 'id="waste-tile-plate-cost"><span class="text-muted" title="cost withheld">—<') && str_contains($h, 'id="waste-row-' . $w1 . '"'), 'a Viewer sees the logs and "—" for cost');
$j = get_json($ann, '/waste/' . $w1);
ok($j['code'] === 200 && !array_key_exists('cost', $j['json']['data']['waste'] ?? ['cost' => 1]), 'the JSON for a Viewer carries no cost key');
$j = get_json($dana, '/waste/' . $w1);
ok(near($j['json']['data']['waste']['cost'] ?? null, $cost1, 0.01), '…for Dana it does');
finish();
